import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import axios from 'axios'; // Make sure axios is imported

const EmployeeManagementPage = () => {
  // `employees` state will now be filled by the API call
  const [employees, setEmployees] = useState([]);
  const [isLoading, setIsLoading] = useState(true);

  // This is the updated useEffect hook for fetching real data
  useEffect(() => {
    const fetchEmployees = async () => {
      setIsLoading(true); // Show the "Loading..." message
      try {
        // --- THIS IS THE REAL API CALL ---
        const response = await axios.get('http://127.0.0.1:8000/api/employees/');

        console.log("Data successfully fetched from backend:", response.data);
        setEmployees(response.data); // Update state with real data

      } catch (error) {
        console.error("There was an error fetching the employee data:", error);

      } finally {
        setIsLoading(false); // Hide the "Loading..." message
      }
    };

    fetchEmployees();
  }, []); // The empty array [] ensures this runs only once when the page loads

  return (
    <>
      <header className="bg-card-light dark:bg-card-dark p-4 flex justify-between items-center border-b border-border-light dark:border-border-dark sticky top-0">
        <h1 className="text-2xl font-semibold text-text-light dark:text-text-dark">Staff & Faculty Directory</h1>
        <Link 
          to="/add-employee" 
          className="bg-primary text-white px-4 py-2 rounded-lg text-sm font-medium flex items-center hover:bg-blue-600"
        >
          <span className="material-icons mr-2 text-base">add</span> Add New Staff
        </Link>
      </header>

      <div className="p-8">
        <div className="bg-card-light dark:bg-card-dark p-6 rounded-lg shadow-md">
          {isLoading ? (
            <div className="text-center py-8">
              <p className="text-subtext-light dark:text-subtext-dark">Loading staff data from the server...</p>
            </div>
          ) : (
            <table className="w-full text-sm text-left">
              <thead className="text-xs text-subtext-light dark:text-subtext-dark uppercase bg-background-light dark:bg-background-dark">
                <tr>
                  {/* === UPDATED TABLE HEADERS TO MATCH YOUR DJANGO MODEL === */}
                  <th className="px-6 py-3">Staff ID</th>
                  <th className="px-6 py-3">Name</th>
                  <th className="px-6 py-3">Designation</th>
                  <th className="px-6 py-3">Department</th>
                  <th className="px-6 py-3">Email</th>
                  <th className="px-6 py-3 text-center">Actions</th>
                </tr>
              </thead>
              <tbody>
                {/* === UPDATED TABLE BODY TO RENDER REAL DATA === */}
                {employees.map((employee) => (
                  <tr key={employee.id} className="border-b border-border-light dark:border-border-dark hover:bg-gray-50 dark:hover:bg-gray-800/50">
                    <td className="px-6 py-4 font-medium text-text-light dark:text-text-dark">{employee.employeeId}</td>
                    <td className="px-6 py-4 font-medium text-text-light dark:text-text-dark">
                      <Link to={`/employees/${employee.id}`} className="hover:text-primary">
                        {/* We combine firstName and lastName for the full name */}
                        {employee.firstName} {employee.lastName}
                      </Link>
                    </td>
                    <td className="px-6 py-4">{employee.designation}</td>
                    <td className="px-6 py-4">{employee.department}</td>
                    <td className="px-6 py-4">{employee.personalEmail}</td>
                    <td className="px-6 py-4 text-center">
                      <button className="text-primary hover:underline text-xs font-medium">Edit</button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          )}
        </div>
      </div>
    </>
  );
};

export default EmployeeManagementPage;
